import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.luI1U3gZ.js";const u=JSON.parse('{"title":"Démarrage rapide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),n={name:"guide/getting-started.md"};function l(d,a,p,r,o,h){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="demarrage-rapide" tabindex="-1">Démarrage rapide <a class="header-anchor" href="#demarrage-rapide" aria-label="Permalink to &quot;Démarrage rapide&quot;">​</a></h1><p>Ce guide crée une application <strong>Nuxt 4 + Quasar 2 + UnoCSS + Pinia + NFZ 6.5.49</strong> avec MongoDB et un compte administrateur de démonstration seedé hors production.</p><h2 id="_1-installer-les-dependances" tabindex="-1">1. Installer les dépendances <a class="header-anchor" href="#_1-installer-les-dependances" aria-label="Permalink to &quot;1. Installer les dépendances&quot;">​</a></h2><p>Utilise <strong>Bun 1.3.6 ou supérieur</strong> pour rester aligné avec NFZ 6.5.49.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="_2-preparer-l-environnement" tabindex="-1">2. Préparer l’environnement <a class="header-anchor" href="#_2-preparer-l-environnement" aria-label="Permalink to &quot;2. Préparer l’environnement&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Le fichier <code>.env.example</code> contient une configuration MongoDB locale prête pour Docker Compose.</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MONGODB_URL=mongodb://root:changeMe@127.0.0.1:27037/nfz_starter?authSource=admin</span></span>
<span class="line"><span>NFZ_DEMO_ENABLED=true</span></span>
<span class="line"><span>NFZ_DEMO_USER=admin</span></span>
<span class="line"><span>NFZ_DEMO_PASSWORD=admin123</span></span>
<span class="line"><span>NFZ_DEMO_ROLES=admin,user</span></span></code></pre></div><h2 id="_3-demarrer-mongodb" tabindex="-1">3. Démarrer MongoDB <a class="header-anchor" href="#_3-demarrer-mongodb" aria-label="Permalink to &quot;3. Démarrer MongoDB&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:up</span></span></code></pre></div><p>Le service MongoDB est exposé localement sur le port <code>27037</code>.</p><h2 id="_4-lancer-nuxt" tabindex="-1">4. Lancer Nuxt <a class="header-anchor" href="#_4-lancer-nuxt" aria-label="Permalink to &quot;4. Lancer Nuxt&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Ou en une commande :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:db</span></span></code></pre></div><h2 id="_5-se-connecter" tabindex="-1">5. Se connecter <a class="header-anchor" href="#_5-se-connecter" aria-label="Permalink to &quot;5. Se connecter&quot;">​</a></h2><p>Compte créé au démarrage par le module de seed Feathers :</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>admin / admin123 (développement uniquement)</span></span></code></pre></div><h2 id="_6-pages-disponibles" tabindex="-1">6. Pages disponibles <a class="header-anchor" href="#_6-pages-disponibles" aria-label="Permalink to &quot;6. Pages disponibles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Rôle</th><th>Description</th></tr></thead><tbody><tr><td><code>/login</code></td><td>public</td><td>Connexion locale Feathers/NFZ</td></tr><tr><td><code>/dashboard</code></td><td>user/admin</td><td>Dashboard protégé</td></tr><tr><td><code>/messages</code></td><td>user/admin</td><td>CRUD message via store Pinia</td></tr><tr><td><code>/session</code></td><td>user/admin</td><td>Diagnostic session/UI</td></tr></tbody></table><h2 id="bonne-pratique" tabindex="-1">Bonne pratique <a class="header-anchor" href="#bonne-pratique" aria-label="Permalink to &quot;Bonne pratique&quot;">​</a></h2><p>Garde le flow suivant :</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pages → stores Pinia → useAdminFeathers() → NFZ/Feathers</span></span></code></pre></div><p>Évite les appels directs à <code>$api.service(...)</code> dans les pages critiques. Cela garde l’auth, la normalisation d’erreurs et la sérialisation des paramètres dans une seule couche maintenable.</p><h2 id="installation-stable-sous-windows" tabindex="-1">Installation stable sous Windows <a class="header-anchor" href="#installation-stable-sous-windows" aria-label="Permalink to &quot;Installation stable sous Windows&quot;">​</a></h2><p>Le starter fournit un <code>bunfig.toml</code> qui limite les scripts postinstall concurrents :</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">concurrentScripts = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>Cela stabilise l&#39;installation des binaires <code>esbuild</code> utilisés par Nuxt/Vite. Après un échec d&#39;installation partielle, utilise :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install:clean:win</span></span></code></pre></div>`,30)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
